module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output              clk_div
);

reg [1:0] state;
reg [2:0] count;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 0;
        count <= 0;
    end else begin
        case (state)
            0: begin
                if (count == 3'd3) begin
                    count <= 0;
                    state <= 1;
                end else begin
                    count <= count + 1;
                end
            end
            1: begin
                if (count == 3'd4) begin
                    count <= 0;
                    state <= 0;
                end else begin
                    count <= count + 1;
                end
            end
        endcase
    end
end

assign clk_div = (state == 0) ? 1'b1 : 1'b0;

endmodule
